    let x4 = q[17]*q[20];
    let x5 = q[18]*q[19];
    let x6 = x4 - x5;
    let x7 = 2.0*g[1];
    let x8 = q[18].powi(2);
    let x9 = q[19].powi(2);
    let x10 = -x9;
    let x11 = q[17].powi(2);
    let x12 = q[20].powi(2);
    let x13 = x11 - x12;
    let x14 = x10 + x13 + x8;
    let x15 = x4 + x5;
    let x16 = 2.0*g[0];
    let x17 = q[17]*q[18];
    let x18 = q[19]*q[20];
    let x19 = x17 - x18;
    let x20 = -x8;
    let x21 = x13 + x20 + x9;
    let x22 = x17 + x18;
    let x23 = x0 - x1;
    let x24 = x10 + x11 + x12 + x20;
    let x25 = 2.0*g[14];
    let x26 = 2.0*g[13];
    let x27 = 2.0*g[12];
    let x28 = 2.0*g[17];
    let x29 = 2.0*g[16];
    let x30 = 2.0*g[15];
    let x31 = 2.0*g[26];
    let x32 = 2.0*g[25];
    let x33 = 2.0*g[24];
    let x34 = 2.0*g[29];
    let x35 = 2.0*g[28];
    let x36 = 2.0*g[27];
    unsafe { MEM[O_WORLD + 0] = g[0]*x14 + q[14] + x2*x3 - x6*x7; }
    unsafe { MEM[O_WORLD + 1] = g[1]*x21 + q[15] + x15*x16 - x19*x3; }
    unsafe { MEM[O_WORLD + 2] = g[2]*x24 + q[16] - x16*x23 + x22*x7; }
    unsafe { MEM[O_WORLD + 3] = g[3]; }
    unsafe { MEM[O_WORLD + 4] = g[4]; }
    unsafe { MEM[O_WORLD + 5] = g[5]; }
    unsafe { MEM[O_WORLD + 6] = g[6]; }
    unsafe { MEM[O_WORLD + 7] = g[7]; }
    unsafe { MEM[O_WORLD + 8] = g[8]; }
    unsafe { MEM[O_WORLD + 9] = g[9]; }
    unsafe { MEM[O_WORLD + 10] = g[10]; }
    unsafe { MEM[O_WORLD + 11] = g[11]; }
    unsafe { MEM[O_WORLD + 12] = g[12]*x14 + q[14] + x2*x25 - x26*x6; }
    unsafe { MEM[O_WORLD + 13] = g[13]*x21 + q[15] + x15*x27 - x19*x25; }
    unsafe { MEM[O_WORLD + 14] = g[14]*x24 + q[16] + x22*x26 - x23*x27; }
    unsafe { MEM[O_WORLD + 15] = g[15]*x14 + q[14] + x2*x28 - x29*x6; }
    unsafe { MEM[O_WORLD + 16] = g[16]*x21 + q[15] + x15*x30 - x19*x28; }
    unsafe { MEM[O_WORLD + 17] = g[17]*x24 + q[16] + x22*x29 - x23*x30; }
    unsafe { MEM[O_WORLD + 18] = g[18]; }
    unsafe { MEM[O_WORLD + 19] = g[19]; }
    unsafe { MEM[O_WORLD + 20] = g[20]; }
    unsafe { MEM[O_WORLD + 21] = g[21]; }
