    unsafe { MEM[O_WORLD + 25] = g[25]*x21 + q[15] + x15*x33 - x19*x31; }
    unsafe { MEM[O_WORLD + 26] = g[26]*x24 + q[16] + x22*x32 - x23*x33; }
