/// Camber, toe, track, contact patch, instant centre and roll centre at the current pose.
/// Parallel or degenerate lines report NaN, which the glue turns into null.
#[no_mangle]
pub extern "C" fn metrics() {
    let mut q = [0.0f64; N];
    let mut g = [0.0f64; G];
    unsafe {
        for i in 0..N { q[i] = MEM[O_Q + i]; }
        for i in 0..G { g[i] = MEM[O_G + i]; }
    }
    let p_wc = [g[24]*(q[17].powi(2) + q[18].powi(2) - q[19].powi(2) - q[20].powi(2)) + g[25]*(-2.0*q[17]*q[20] + 2.0*q[18]*q[19]) + g[26]*(2.0*q[17]*q[19] + 2.0*q[18]*q[20]) + q[14], g[24]*(2.0*q[17]*q[20] + 2.0*q[18]*q[19]) + g[25]*(q[17].powi(2) - q[18].powi(2) + q[19].powi(2) - q[20].powi(2)) + g[26]*(-2.0*q[17]*q[18] + 2.0*q[19]*q[20]) + q[15], g[24]*(-2.0*q[17]*q[19] + 2.0*q[18]*q[20]) + g[25]*(2.0*q[17]*q[18] + 2.0*q[19]*q[20]) + g[26]*(q[17].powi(2) - q[18].powi(2) - q[19].powi(2) + q[20].powi(2)) + q[16]];
    let p_wco = [g[27]*(q[17].powi(2) + q[18].powi(2) - q[19].powi(2) - q[20].powi(2)) + g[28]*(-2.0*q[17]*q[20] + 2.0*q[18]*q[19]) + g[29]*(2.0*q[17]*q[19] + 2.0*q[18]*q[20]) + q[14], g[27]*(2.0*q[17]*q[20] + 2.0*q[18]*q[19]) + g[28]*(q[17].powi(2) - q[18].powi(2) + q[19].powi(2) - q[20].powi(2)) + g[29]*(-2.0*q[17]*q[18] + 2.0*q[19]*q[20]) + q[15], g[27]*(-2.0*q[17]*q[19] + 2.0*q[18]*q[20]) + g[28]*(2.0*q[17]*q[18] + 2.0*q[19]*q[20]) + g[29]*(q[17].powi(2) - q[18].powi(2) - q[19].powi(2) + q[20].powi(2)) + q[16]];
    let p_lbj = [g[0]*(q[17].powi(2) + q[18].powi(2) - q[19].powi(2) - q[20].powi(2)) + g[1]*(-2.0*q[17]*q[20] + 2.0*q[18]*q[19]) + g[2]*(2.0*q[17]*q[19] + 2.0*q[18]*q[20]) + q[14], g[0]*(2.0*q[17]*q[20] + 2.0*q[18]*q[19]) + g[1]*(q[17].powi(2) - q[18].powi(2) + q[19].powi(2) - q[20].powi(2)) + g[2]*(-2.0*q[17]*q[18] + 2.0*q[19]*q[20]) + q[15], g[0]*(-2.0*q[17]*q[19] + 2.0*q[18]*q[20]) + g[1]*(2.0*q[17]*q[18] + 2.0*q[19]*q[20]) + g[2]*(q[17].powi(2) - q[18].powi(2) - q[19].powi(2) + q[20].powi(2)) + q[16]];
    let p_ubj = [g[15]*(q[17].powi(2) + q[18].powi(2) - q[19].powi(2) - q[20].powi(2)) + g[16]*(-2.0*q[17]*q[20] + 2.0*q[18]*q[19]) + g[17]*(2.0*q[17]*q[19] + 2.0*q[18]*q[20]) + q[14], g[15]*(2.0*q[17]*q[20] + 2.0*q[18]*q[19]) + g[16]*(q[17].powi(2) - q[18].powi(2) + q[19].powi(2) - q[20].powi(2)) + g[17]*(-2.0*q[17]*q[18] + 2.0*q[19]*q[20]) + q[15], g[15]*(-2.0*q[17]*q[19] + 2.0*q[18]*q[20]) + g[16]*(2.0*q[17]*q[18] + 2.0*q[19]*q[20]) + g[17]*(q[17].powi(2) - q[18].powi(2) - q[19].powi(2) + q[20].powi(2)) + q[16]];
    let axle = sub3(p_wco, p_wc);
    let an = norm3(axle);
    let n = [axle[0] / an, axle[1] / an, axle[2] / an];
    let centre = [(p_wc[0] + p_wco[0]) * 0.5,
                  (p_wc[1] + p_wco[1]) * 0.5,
                  (p_wc[2] + p_wco[2]) * 0.5];
    // the lowest point of the wheel disc: down, projected into the wheel plane
    let in_plane = [n[2] * n[0], n[2] * n[1], n[2] * n[2] - 1.0];
    let scale = norm3(in_plane);
    let contact3 = [centre[0] + 2.00000000000000011e-01 * in_plane[0] / scale,
                    centre[1] + 2.00000000000000011e-01 * in_plane[1] / scale,
                    centre[2] + 2.00000000000000011e-01 * in_plane[2] / scale];
    let contact = [contact3[0], contact3[2]];
    let camber = (-n[2]).asin().to_degrees();
    let mut toe = n[1].atan2(n[0]).to_degrees() - 0.00000000000000000e+00;
    if toe > 180.0 { toe -= 360.0; } else if toe < -180.0 { toe += 360.0; }
    let track = contact[0] - 8.10000000000000053e-01;
    let foot_l = [2.99999999999999989e-01, 1.01906412505002597e-02, 1.54575389979951350e-01];
    let foot_u = [3.80000000000000004e-01, 2.24438902743144542e-03, 4.75112219451371554e-01];
    let d_l = sub3(foot_l, p_lbj);
    let d_u = sub3(foot_u, p_ubj);
    let ic = intersect2([p_lbj[0], p_lbj[2]], [d_l[0], d_l[2]],
                        [p_ubj[0], p_ubj[2]], [d_u[0], d_u[2]]);
    let rc = if (ic[0] - contact[0]).abs() < 1e-12 {
        [f64::NAN, f64::NAN]
    } else {
        let t = (0.0 - contact[0]) / (ic[0] - contact[0]);
        [0.0, contact[1] + t * (ic[1] - contact[1])]
    };
    unsafe {
        MEM[O_MET + 0] = camber;
        MEM[O_MET + 1] = toe;
        MEM[O_MET + 2] = track;
        MEM[O_MET + 3] = contact[0];
        MEM[O_MET + 4] = contact[1];
        MEM[O_MET + 5] = ic[0];
        MEM[O_MET + 6] = ic[1];
        MEM[O_MET + 7] = rc[0];
        MEM[O_MET + 8] = rc[1];
        MEM[O_MET + 9] = 0.0;
    }
}

#[inline]
fn solve_linear(n: usize, a: &mut [f64], b: &mut [f64]) -> bool {
    for col in 0..n {
        let mut pivot = col;
        let mut best = a[col*n + col].abs();
        for row in col+1..n {
            let value = a[row*n + col].abs();
            if value > best { best = value; pivot = row; }
        }
        if best < 1e-14 { return false; }
        if pivot != col {
            for k in 0..n { a.swap(col*n + k, pivot*n + k); }
            b.swap(col, pivot);
        }
        let d = a[col*n + col];
        for row in col+1..n {
            let f = a[row*n + col] / d;
            if f != 0.0 {
                for k in col..n { a[row*n + k] -= f * a[col*n + k]; }
                b[row] -= f * b[col];
            }
        }
    }
    for row in (0..n).rev() {
        let mut s = b[row];
        for k in row+1..n { s -= a[row*n + k] * b[k]; }
        b[row] = s / a[row*n + row];
    }
    true
}

#[inline]
fn residual(q: &[f64; N], g: &[f64; G], t: &[f64; A], out: &mut [f64; M], jac: &mut [f64; N*M]) -> f64 {
    compute_inner(q, g, t, out, jac);
    let mut worst = 0.0f64;
    for i in 0..M { let v = out[i].abs(); if v > worst { worst = v; } }
    worst
}

/// Levenberg–Marquardt from the current Q, for a redundant model. Returns the infinity
/// norm of the residual; -1 means the normal equations were singular.
#[no_mangle]
pub extern "C" fn solve(iters: i32) -> f64 {
    let mut q = [0.0f64; N];
    let mut g = [0.0f64; G];
    let mut t = [0.0f64; A];
    unsafe {
        for i in 0..N { q[i] = MEM[O_Q + i]; }
        for i in 0..G { g[i] = MEM[O_G + i]; }
        for i in 0..A { t[i] = MEM[O_T + i]; }
    }
    let mut out = [0.0f64; M];
    let mut jac = [0.0f64; N*M];
    let mut worst = residual(&q, &g, &t, &mut out, &mut jac);
    let mut lambda = 1e-6f64;
    for _ in 0..iters {
        if worst < 1e-12 { break; }
        let mut a = [0.0f64; N*N];
        let mut b = [0.0f64; N];
        for i in 0..M {
            for p in 0..N { b[p] -= jac[i*N + p] * out[i]; }
        }
        for p in 0..N {
            for r in 0..N {
                let mut s = 0.0f64;
                for i in 0..M { s += jac[i*N + p] * jac[i*N + r]; }
                a[p*N + r] = s;
            }
        }
        for d in 0..N { a[d*N + d] += lambda * (a[d*N + d] + 1e-12); }
        if !solve_linear(N, &mut a, &mut b) { return -1.0; }
        let mut trial = q;
        for i in 0..N { trial[i] += b[i]; }
        let mut out_trial = [0.0f64; M];
        let mut jac_trial = [0.0f64; N*M];
        let value = residual(&trial, &g, &t, &mut out_trial, &mut jac_trial);
        if value < worst {
            q = trial; out = out_trial; jac = jac_trial; worst = value;
            lambda = (lambda * 0.3).max(1e-12);
        } else {
            lambda = (lambda * 10.0).min(1e9);
        }
    }
    unsafe { for i in 0..N { MEM[O_Q + i] = q[i]; } }
    worst
}
